def verificar_pin(cid, pin):
    p = load_cli(cid)
    if not p: return False
    pin_salvo = p.get("pin","")
    if not pin_salvo: return True  # sem pin = acesso livre
    return str(pin) == str(pin_salvo)

def ls_cli():
    out=[]
    for a in os.listdir(PASTA):
        if a.endswith(".json") and not a.endswith("_cenarios_ml.json"):
            try:
                with open(os.path.join(PASTA,a),encoding="utf-8") as f: d=json.load(f)
                if "nome" not in d: continue
                out.append({"id":a[:-5],"nome":d.get("nome","?"),"at":d.get("meta",{}).get("at","")[:10]})
            except: pass
    return sorted(out,key=lambda x:x["nome"].lower())

def pre_carregar_cliente(cid):
    if not cid: return
    _res,_cal,_morto=load_resultado_compras(cid)
    if _res is not None:
        st.session_state["compras_resultado"]=_res
        st.session_state["compras_calendario"]=_cal
        st.session_state["compras_morto"]=_morto
    _est=load_estoque_compras(cid)
    if _est is not None: st.session_state["compras_df_estoque"]=_est
    # Removido: pré-carregar cfgml_resultado aqui usava filial=None (cai no arquivo
    # "Todas as filiais"/consolidado) e jogava isso na sessão ANTES do usuário
    # escolher a filial na tela — a página do Motor de Previsão já carrega sob
    # demanda, com a filial certa (cfgml_filial_sel_pag), então isso só causava
    # F5 mostrando resultado de "Todas as filiais" (ou o que estivesse ali) em
    # vez do resultado da filial que a pessoa realmente estava vendo.
    _val_full=load_validacao_full(cid)
    if _val_full is not None and _val_full.get("df_comp") is not None:
        st.session_state["cfgml_df_comp_bruto"]=_val_full["df_comp"]
        st.session_state["cfgml_df_escopo_val"]=_val_full["df_escopo"]
        st.session_state["cfgml_produto_col_val_usado"]=_val_full["produto_col"]
        st.session_state["cfgml_col_data_val_usado"]=_val_full["col_data"]
        st.session_state["cfgml_metrica_val_usado"]=_val_full["metrica"]
    _calib_ml=load_calibracoes_ml(cid)
    if _calib_ml:
        for _k_calib,_v_calib in _calib_ml.items():
            st.session_state[_k_calib]=_v_calib
    _modelos_vencedores_salvos,_escopo_vencedores_salvo=load_modelos_vencedores(cid)
    if _modelos_vencedores_salvos:
        st.session_state["mlp_modelos_vencedores"]=_modelos_vencedores_salvos
        st.session_state["mlp_modelos_vencedores_escopo"]=_escopo_vencedores_salvo
    _ff_salvo=load_fluxo_financeiro(cid)
    if _ff_salvo:
        st.session_state["ff_parcelas_pagar"]=_ff_salvo.get("ff_parcelas_pagar") or [{"pct":100,"dias":30}]
        st.session_state["ff_parcelas_receber"]=_ff_salvo.get("ff_parcelas_receber") or [{"pct":100,"dias":30}]
        st.session_state["ff_encargos_pct"]=_ff_salvo.get("ff_encargos_pct") or 0.0
        st.session_state["ff_saldo_inicial"]=_ff_salvo.get("ff_saldo_inicial") or 0.0
        st.session_state["ff_incluir_contas_pr"]=_ff_salvo.get("ff_incluir_contas_pr") or False
        st.session_state["ff_config_carregada"]=True
    _cp=load_contas_pr(cid,"pagar")
    if _cp is not None: st.session_state["ff_contas_pagar_df"]=_cp
    _cr=load_contas_pr(cid,"receber")
    if _cr is not None: st.session_state["ff_contas_receber_df"]=_cr
    _sc_forn=load_scorecard_forn(cid)
    if _sc_forn is not None: st.session_state["gs_scorecard_forn"]=_sc_forn
    # Limpa o cache da tela de Validação Estatística — sem isso, trocar de cliente
    # deixava o resultado do cliente ANTERIOR na tela até rodar de novo manualmente
    # (vazamento de dado entre clientes na mesma sessão).
    for _k_limpar_troca_cliente in ["ml_produtos_resultado","mlp_produto_col_atual",
            "mlp_metrica_col_atual","mlp_data_col_atual","vendas_raw_com_chave",
            "mlp_validacao_resultado","mlp_validacao_ranks",
            "mlp_filial_sel_backup","mlp_categoria_sel_backup","mlp_curva_sel_backup",
            "mlp_resultado_categoria_usada","mlp_resultado_curva_usada"]:
        if _k_limpar_troca_cliente in st.session_state:
            del st.session_state[_k_limpar_troca_cliente]
    _cfg_ml_config=load_config_ml(cid)
    if _cfg_ml_config:
        for _k,_v in _cfg_ml_config.items():
            st.session_state[_k]=_v
        st.session_state["cfgml_config_carregada"]=True
    # Restauração customizada de "cfgml_crescimento_por_produto" removida —
    # agora leva sufixo de Categoria e já é restaurada pelo load_config_ml
    # genérico logo acima, que preserva cada chave exatamente como foi salva.
    # Restauração customizada de "mlf_crescimento_por_conta" removida — agora
    # a chave leva sufixo de Demonstração e já é restaurada automaticamente
    # pelo load_config_ml genérico (linha ~379), que preserva cada chave
    # (incluindo o sufixo) exatamente como foi salva.
    _cache_previsao_conta_mlf_disco=load_cache_previsao_conta_mlf(cid)
    if _cache_previsao_conta_mlf_disco:
        st.session_state["mlf_cache_previsao_conta"]=_cache_previsao_conta_mlf_disco
    _cfg_compras=load_config_compras(cid)
    if _cfg_compras:
        for _k,_v in _cfg_compras.items():
            st.session_state[_k]=_v
    _lt_compras=load_leadtime_compras(cid)
    if _lt_compras:
        for _k,_v in _lt_compras.items():
            st.session_state[_k]=_v
    _cfg_mlp=load_config_mlp(cid)
    if _cfg_mlp:
        for _k,_v in _cfg_mlp.items():
            if _v is not None:
                st.session_state[_k]=_v
    _pv=load_snap(cid,"pareto_visao")
    if _pv: st.session_state["pareto_visao"]=_pv.get("visao","")
    # O resultado do Pareto (pareto_resultado_atual) não é mais pré-carregado aqui —
    # a própria página de Pareto já recarrega do disco sozinha quando necessário,
    # de forma correta e ciente de Filial (evita o "achou que você trocou de visão" à toa).    

def renderizar_card_cliente(c,prefixo="ab"):
    c1,c2,c3,c4=st.columns([4,2,1,1])
    p2=load_cli(c["id"]); tem_pin=bool(p2.get("pin","")) if p2 else False
    c1.markdown(f'<div style="color:#111827;font-weight:600;padding:10px 0">'
               f'{c["nome"]} {"🔒" if tem_pin else "🔓"}</div>',unsafe_allow_html=True)
    c2.markdown(f'<div style="color:#9CA3AF;font-size:.82rem;padding:12px 0">🕐 {c["at"]}</div>',unsafe_allow_html=True)
    if c3.button("📂 Abrir",key=f"{prefixo}_{c['id']}",use_container_width=True):
        if tem_pin:
            st.session_state.pin_pendente=c["id"]
        else:
            limpar_sessao_cliente()
            p_open=load_cli(c["id"])
            st.session_state.cid=c["id"]
            st.session_state.df_raw=load_df(c["id"])
            st.session_state.projecoes={}
            st.session_state.saldo_ini=float(p_open.get("saldo_ini",0)) if p_open else 0.
            st.session_state.entradas_vista=float(p_open.get("entradas_vista",0)) if p_open else 0.
            st.session_state.freq_fluxo=p_open.get("freq_fluxo","Mensal") if p_open else "Mensal"
            st.session_state["_limpar_busca_cliente"]=True
            pre_carregar_cliente(c["id"])
            addlog(f"'{c['nome']}' aberto"); ir("boas_vindas")
    if c4.button("🗑",key=f"{prefixo}_dl_{c['id']}",use_container_width=True):
        st.session_state[f"_confirmar_exclusao_{c['id']}"]=True
        st.rerun()
    if st.session_state.get(f"_confirmar_exclusao_{c['id']}"):
        st.markdown('<div class="al-d">⚠️ Excluir apaga o cadastro desse cliente permanentemente. '
                    'Digite a senha master pra confirmar.</div>',unsafe_allow_html=True)
        _senha_del_cli=st.text_input("Senha master",type="password",key=f"{prefixo}_senha_del_{c['id']}")
        cdel1,cdel2=st.columns(2)
        if cdel1.button("✅ Confirmar exclusão",key=f"{prefixo}_confirma_del_{c['id']}",use_container_width=True):
            if _senha_del_cli!=SENHA_MASTER:
                st.error("❌ Senha master incorreta.")
            else:
                os.remove(path_cli(c["id"]))
                if st.session_state.cid==c["id"]: st.session_state.cid=None; st.session_state.df_raw=None
                del st.session_state[f"_confirmar_exclusao_{c['id']}"]
                st.rerun()
        if cdel2.button("Cancelar",key=f"{prefixo}_cancela_del_{c['id']}",use_container_width=True):
            del st.session_state[f"_confirmar_exclusao_{c['id']}"]
            st.rerun()
    st.divider()

def save_df(cid,df):
    _path_dados=os.path.join(PASTA,f"{gid(cid)}_dados.csv")
    # Backup automático ANTES de sobrescrever — se o arquivo já existe,
    # copia ele com timestamp antes de substituir. Protege contra perda
    # acidental (ex: uma importação errada apagando dados corretos que já
    # estavam lá). Mantém só os 5 backups mais recentes, pra não acumular
    # arquivo infinito.
    try:
        if os.path.exists(_path_dados):
            _pasta_backup=os.path.join(PASTA,"_backups")
            os.makedirs(_pasta_backup,exist_ok=True)
            _timestamp_bkp=datetime.now().strftime("%Y%m%d_%H%M%S")
            _nome_bkp=f"{gid(cid)}_dados_{_timestamp_bkp}.csv"
            shutil.copy2(_path_dados,os.path.join(_pasta_backup,_nome_bkp))
            # Limpa backups antigos — mantém só os 5 mais recentes desse cliente
            _backups_cliente=sorted(
                [f for f in os.listdir(_pasta_backup) if f.startswith(f"{gid(cid)}_dados_")],
                reverse=True)
            for _bkp_antigo in _backups_cliente[5:]:
                try: os.remove(os.path.join(_pasta_backup,_bkp_antigo))
                except Exception: pass
    except Exception:
        pass  # nunca deixa uma falha de backup impedir o salvamento principal
    df.to_csv(_path_dados,sep=";",decimal=",",index=False,encoding="utf-8-sig")

