                _resultados_lojas=[]
                _calendarios_lojas=[]
                for _fil_x in _filiais_lista:
                    _res_fil,_cal_fil,_morto_fil=load_resultado_compras(st.session_state.cid,_fil_x) if st.session_state.cid else (None,None,None)
